AOS.init({duration:700,once:true});(function(){const t=document.getElementById("theme-toggle"),e=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches,s=localStorage.getItem("theme");if(s==="dark"||(!s&&e))document.body.classList.add("dark-theme");if(t){t.addEventListener("click",()=>{const n=document.body.classList.toggle("dark-theme");localStorage.setItem("theme",n?"dark":"light")})}document.querySelectorAll(".nav-link").forEach(l=>{l.addEventListener("click",function(a){a.preventDefault();const r=this.getAttribute("href");if(!r||r==="#")return;const o=document.querySelector(r);o&&o.scrollIntoView({behavior:"smooth",block:"start"})})})})();(function(){const t="image/fto.jpg";document.querySelectorAll("img").forEach(e=>{e.addEventListener("error",()=>{if(e.src&&!e.dataset.fallbackApplied){e.dataset.fallbackApplied="1";e.src=t;e.classList.add("img-fallback")}});if(e.complete&&e.naturalWidth===0){e.dispatchEvent(new Event("error"))}})})();
